"""Source-reviewed variance summaries. Not a technical design checklist."""
import pathlib,json,re
out=pathlib.Path(__file__).resolve().parent
notes=json.loads((out/'reviewed-notes.json').read_text()) if (out/'reviewed-notes.json').exists() else {}
records=json.loads((out/'index.json').read_text())

def put(ids,summary,scope,conditions,cites,topics,**extra):
 for r in records:
  code=re.search(r'\d{2}-bcv-\d{3}(?:r\d+|-rev\d+)?$',r['id'])
  if code and code[0] in ids.split():
   notes[r['id']]=dict(summary=summary,applies_to=scope,conditions=conditions.split('|'),selected_citations=cites.split(),topics=topics.split(),conditions_completeness='Navigation summary of operative conditions; read every condition, table, diagram and limitation in the source before use.',**extra)
 def save():
  (out/'reviewed-notes.json').write_text(json.dumps(notes,indent=2,ensure_ascii=False)+'\n')
 save()

